type Contract struct {
    customer, supplier string // compulsory: unexported, settable only here
    start              time.Time
}

// NewContract is the Essence: validation happens before any value escapes.
func NewContract(customer, supplier string, start time.Time) (*Contract, error) {
    if customer == "" || supplier == "" || start.IsZero() {
        return nil, fmt.Errorf("contract: customer, supplier and start are compulsory")
    }
    return &Contract{customer: customer, supplier: supplier, start: start}, nil
}
